  id: number
  title: string
}

let nextId = 1
const posts: Post[] = []

export function addPost(title: string): Post {
  const post: Post = { id: nextId++, title }
  posts.push(post)
  return post
}

export function getPosts(): Post[] {
  return [...posts]
}

